//! HDF5 parity gate (feature `hdf5`): the Rust-written `solution.h5`
//! against the C oracle's format contract and the slice's proven field
//! values.
//!
//! Three pins:
//! 1. a fresh write of the smoke snapshot read back field-by-field —
//!    values bit-identical to `l1_smoke_n64_solution.txt` (SAN-62's
//!    C-oracle parity state), coordinates matching the C meshgrids,
//!    attributes matching the smoke spec exactly (names AND types);
//! 2. the committed Rust fixture
//!    (`tests/fixtures/l1_smoke_n64_rust.h5`, regenerated by
//!    `examples/l1_smoke_snapshot.rs`) carries the same values;
//! 3. a fresh write reproduces the committed fixture's datasets and
//!    attribute set bit-for-bit (layout regression net; provenance
//!    values are excluded by name).
//!
//! The Python cross-read (`tools/rotboson_io.py` loads BOTH the C and
//! Rust files) is a manual step — no Python in cargo test:
//!
//! ```sh
//! uv run python3 -c 'import sys; sys.path.insert(0, "tools"); import rotboson_io as rio; \
//!   c, _ = rio.read_hdf5("<c-oracle-dir>/solution.h5"); \
//!   r, _ = rio.read_hdf5("<rust-dir>/solution.h5"); \
//!   import numpy as np; \
//!   print({k: float(np.abs(c[k] - r[k]).max()) for k in r if k in c})'
//! ```
#![cfg(feature = "hdf5")]

mod common;

use std::collections::BTreeSet;

use rbs_io::hdf5::{Hdf5Writer, SnapshotAttrs};
use rbs_io::{FieldBlock, GridTopology};

const PARITY_TOL: f64 = 1e-15;

/// The exact attribute name set a smoke snapshot must carry (the C
/// writer's contract minus the analysis blocks, which are emitted only
/// when computed).
const SMOKE_ATTRS: [&str; 49] = [
    // provenance
    "git_hash", "parfile", "output_backend", "created", "format_version",
    // GRID
    "dr", "dz", "NrInterior", "NzInterior", "NrTotal", "NzTotal", "dim", "ghost", "order",
    // SCALAR FIELD + FIXED VARIABLE
    "l", "m", "psi0", "sigmaR", "sigmaZ", "rExt", "w0", "w_idx", "fixedPhi", "fixedPhiR",
    "fixedPhiZ", "fixedOmega",
    // INITIAL DATA
    "readInitialData", "NrTotalInitial", "NzTotalInitial", "ghost_i", "order_i", "dr_i",
    "dz_i",
    // SCALE INITIAL DATA
    "scale_u0", "scale_u1", "scale_u2", "scale_u3", "scale_u4", "scale_u5", "scale_u6",
    // SOLVER + GUESS CHECK
    "solverType", "localSolver", "epsilon", "maxNewtonIter", "lambda0", "lambdaMin",
    "useLowRank", "max_initial_guess_checks", "norm_f0_target",
];

fn expect_i64(f: &hdf5::File, name: &str, v: i64) {
    assert_eq!(
        f.attr(name)
            .unwrap_or_else(|e| panic!("attr {name} present: {e}"))
            .read_scalar::<i64>()
            .unwrap_or_else(|e| panic!("attr {name} is i64: {e}")),
        v,
        "attr {name}"
    );
}

fn expect_f64(f: &hdf5::File, name: &str, v: f64) {
    let got = f
        .attr(name)
        .unwrap_or_else(|e| panic!("attr {name} present: {e}"))
        .read_scalar::<f64>()
        .unwrap_or_else(|e| panic!("attr {name} is f64: {e}"));
    assert!(
        (got - v).abs() <= 1e-15,
        "attr {name}: got {got:e}, want {v:e}"
    );
}

fn expect_str(f: &hdf5::File, name: &str) -> String {
    f.attr(name)
        .unwrap_or_else(|e| panic!("attr {name} present: {e}"))
        .read_scalar::<hdf5::types::VarLenUnicode>()
        .unwrap_or_else(|e| panic!("attr {name} is a string: {e}"))
        .to_string()
}

/// Assert the smoke spec's attribute values (typed), against the exact
/// spec numbers from configs/l1_smoke_ci.toml @ epsilon=1e-12.
fn check_smoke_attrs(f: &hdf5::File, attrs: &SnapshotAttrs) {
    let names: BTreeSet<String> = f
        .attr_names()
        .expect("attr names")
        .into_iter()
        .collect();
    let want: BTreeSet<String> = SMOKE_ATTRS.iter().map(|s| (*s).to_string()).collect();
    assert_eq!(
        names, want,
        "attribute name set is exactly the smoke contract (extra: {:?}, missing: {:?})",
        names.difference(&want).collect::<Vec<_>>(),
        want.difference(&names).collect::<Vec<_>>()
    );

    // Provenance: names + types pinned, values are snapshot-time data.
    assert!(!expect_str(f, "git_hash").is_empty());
    assert!(!expect_str(f, "parfile").is_empty());
    assert_eq!(expect_str(f, "output_backend"), attrs.backend);
    let created = expect_str(f, "created");
    assert_eq!(created.len(), 20, "created is ISO 8601 UTC: {created}");
    assert!(created.ends_with('Z') && created.as_bytes()[10] == b'T', "{created}");
    expect_i64(f, "format_version", 1);

    // GRID (NrTotal/NzTotal/dim synced to the written grid).
    expect_f64(f, "dr", 0.25);
    expect_f64(f, "dz", 0.25);
    expect_i64(f, "NrInterior", 64);
    expect_i64(f, "NzInterior", 64);
    expect_i64(f, "NrTotal", 68);
    expect_i64(f, "NzTotal", 68);
    expect_i64(f, "dim", 4624);
    expect_i64(f, "ghost", 2);
    expect_i64(f, "order", 4);

    // SCALAR FIELD + FIXED VARIABLE.
    expect_i64(f, "l", 1);
    expect_f64(f, "m", 1.0);
    expect_f64(f, "psi0", 0.01);
    expect_f64(f, "sigmaR", 4.0);
    expect_f64(f, "sigmaZ", 4.0);
    expect_f64(f, "rExt", 12.0);
    expect_f64(f, "w0", 0.95);
    expect_i64(f, "w_idx", 27_744); // GNUM * dim = 6 * 4624
    expect_i64(f, "fixedPhi", 0);
    expect_i64(f, "fixedPhiR", 4); // context.c defaults (unused at fixedOmega=1)
    expect_i64(f, "fixedPhiZ", 4);
    expect_i64(f, "fixedOmega", 1);

    // INITIAL DATA.
    expect_i64(f, "readInitialData", 0);
    expect_i64(f, "NrTotalInitial", 0);
    expect_i64(f, "NzTotalInitial", 0);
    expect_i64(f, "ghost_i", 1);
    expect_i64(f, "order_i", 2);
    expect_f64(f, "dr_i", 1.0);
    expect_f64(f, "dz_i", 1.0);

    // SCALE INITIAL DATA.
    for i in 0..7 {
        expect_f64(f, &format!("scale_u{i}"), 1.0);
    }

    // SOLVER + GUESS CHECK (fixture generation protocol).
    expect_i64(f, "solverType", 1);
    expect_i64(f, "localSolver", 1);
    expect_f64(f, "epsilon", 1e-12);
    expect_i64(f, "maxNewtonIter", 40);
    expect_f64(f, "lambda0", 1e-3);
    expect_f64(f, "lambdaMin", 1e-5);
    expect_i64(f, "useLowRank", 0);
    expect_i64(f, "max_initial_guess_checks", 8);
    expect_f64(f, "norm_f0_target", 1e-5);
}

/// Assert the field datasets against the slice fixture's values and the
/// C meshgrid layout.
fn check_datasets(f: &hdf5::File, snap: &common::SmokeSnapshot) {
    let (nr, nz) = (snap.grid.nr, snap.grid.nz);

    // Fields: 2D (NrTotal, NzTotal), row-major IDX(i, j), values equal
    // to the proven parity state within the parity tolerance (HDF5
    // stores exact f64s, so this is expected to be 0.0).
    for field in &snap.fields {
        let d = f
            .dataset(&format!("{}.asc", field.name))
            .unwrap_or_else(|e| panic!("dataset {}.asc: {e}", field.name));
        assert_eq!(d.shape(), [nr, nz], "{}.asc is (NrTotal, NzTotal)", field.name);
        let got = d.read_raw::<f64>().expect("f64 values");
        let diff = common::max_abs_diff(&got, &field.values);
        assert!(
            diff <= PARITY_TOL,
            "{}.asc vs slice fixture: max_abs {diff:e} > {PARITY_TOL:e}",
            field.name
        );
    }

    // w_f: 1D, exactly the fixed omega.
    let w_f = f.dataset("w_f.asc").expect("w_f.asc");
    assert_eq!(w_f.shape(), [1]);
    assert_eq!(w_f.read_raw::<f64>().unwrap(), vec![snap.omega]);

    // r/z: 2D meshgrids, r constant along rows, z along columns
    // (main.c's construction), matching the C h5 layout exactly.
    let r = f.dataset("r.asc").unwrap().read_2d::<f64>().unwrap();
    let z = f.dataset("z.asc").unwrap().read_2d::<f64>().unwrap();
    assert_eq!(r.shape(), [nr, nz]);
    for i in 0..nr {
        for j in 0..nz {
            assert_eq!(r[[i, j]], snap.grid.r[i], "r.asc[i, j] = r_i");
            assert_eq!(z[[i, j]], snap.grid.z[j], "z.asc[i, j] = z_j");
        }
    }
    // First interior cell at dr/2; ghost band below the axis.
    assert!((r[[2, 0]] - 0.125).abs() < 1e-12);
    assert!((r[[0, 0]] + 0.375).abs() < 1e-12);
}

fn write_smoke_to(dir: &std::path::Path) -> std::path::PathBuf {
    let snap = common::load_smoke();
    let attrs = common::smoke_attrs("test-hash", "test parfile");
    let path = dir.join("solution.h5");
    let mut w = Hdf5Writer::new(&path);
    let w_f = snap.w_f();
    w.write_snapshot_with(&snap.grid, &snap.fields, &[w_f], &[], &attrs)
        .expect("write smoke snapshot");
    path
}

#[test]
fn fresh_write_matches_slice_fixture() {
    let dir = std::env::temp_dir().join(format!("rbs-io-h5-par-{}", std::process::id()));
    std::fs::create_dir_all(&dir).expect("mkdir");
    let path = write_smoke_to(&dir);
    let f = hdf5::File::open(&path).expect("reopen");
    let snap = common::load_smoke();
    check_datasets(&f, &snap);
    check_smoke_attrs(&f, &common::smoke_attrs("test-hash", "test parfile"));
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn committed_fixture_matches_slice_fixture() {
    let path = common::rust_h5_fixture_path();
    common::require(&path);
    let f = hdf5::File::open(&path).expect("open committed fixture");
    let snap = common::load_smoke();
    check_datasets(&f, &snap);
    check_smoke_attrs(&f, &common::smoke_attrs("test-hash", "test parfile"));
}

#[test]
fn fresh_write_reproduces_the_committed_fixture() {
    let path = common::rust_h5_fixture_path();
    common::require(&path);
    let dir = std::env::temp_dir().join(format!("rbs-io-h5-reg-{}", std::process::id()));
    std::fs::create_dir_all(&dir).expect("mkdir");
    let fresh = write_smoke_to(&dir);

    let committed = hdf5::File::open(&path).expect("open committed");
    let new = hdf5::File::open(&fresh).expect("open fresh");

    // Dataset name sets identical, every dataset bit-identical.
    let committed_keys: BTreeSet<String> =
        committed.member_names().expect("committed datasets").into_iter().collect();
    let new_keys: BTreeSet<String> =
        new.member_names().expect("fresh datasets").into_iter().collect();
    assert_eq!(committed_keys, new_keys, "same dataset set");
    for k in &committed_keys {
        let a = committed.dataset(k).unwrap().read_raw::<f64>().unwrap();
        let b = new.dataset(k).unwrap().read_raw::<f64>().unwrap();
        assert_eq!(a, b, "dataset {k} bit-identical");
        assert_eq!(
            committed.dataset(k).unwrap().shape(),
            new.dataset(k).unwrap().shape()
        );
    }

    // Attribute name sets identical; values identical except provenance.
    let prov = ["git_hash", "created", "parfile"];
    let fresh_names: BTreeSet<String> =
        new.attr_names().expect("fresh attrs").into_iter().collect();
    for name in committed.attr_names().expect("committed attrs") {
        if prov.contains(&name.as_str()) {
            continue;
        }
        assert!(
            fresh_names.contains(&name),
            "attr {name} present in a fresh write"
        );
    }
    // Provenance values may differ; the committed ones must be non-empty.
    for name in prov {
        assert!(!expect_str(&committed, name).is_empty(), "{name} recorded");
    }
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn grid_attrs_are_synced_not_trusted() {
    // A caller describing the wrong grid gets the file's own truth.
    let dir = std::env::temp_dir().join(format!("rbs-io-h5-sync-{}", std::process::id()));
    std::fs::create_dir_all(&dir).expect("mkdir");
    let grid = GridTopology::centered(10, 8, 0.5, 0.25, 1);
    let mut attrs = common::smoke_attrs("x", "x");
    attrs.grid.nr_total = 999; // stale
    let mut w = Hdf5Writer::new(dir.join("solution.h5"));
    w.write_snapshot_with(
        &grid,
        &[FieldBlock {
            name: "psi".to_string(),
            values: vec![0.0; 80],
        }],
        &[],
        &[],
        &attrs,
    )
    .expect("write");
    let f = hdf5::File::open(w.path()).expect("reopen");
    expect_i64(&f, "NrTotal", 10);
    expect_i64(&f, "NzTotal", 8);
    expect_i64(&f, "dim", 80);
    let _ = std::fs::remove_dir_all(&dir);
}
